/** Closed fictional EN specialist journey; no provider, effect execution or forged evaluation. */
import assert from 'node:assert/strict';
export const SPECIALIST_MODULES=Object.freeze(['employees','org','leave','ess','approvals','knowledge_base','payroll','attendance','claims','performance','rewards','lifecycle','toil','multi_cycle_payroll','typed_pay_components','country-my','notifications','system_explorer','assistant','system_testing']);
export const GAIN_MODULES=Object.freeze(['org','leave','attendance','claims','performance']);
export const SPECIALIST_PHASES=Object.freeze(['baseline',...SPECIALIST_MODULES.map(m=>'baseline:'+m),...SPECIALIST_MODULES.map(m=>'create:'+m),...SPECIALIST_MODULES.map(m=>'evaluate1:'+m),...SPECIALIST_MODULES.map(m=>'evaluate2:'+m),...SPECIALIST_MODULES.map(m=>(GAIN_MODULES.includes(m)?'promote:':'no_gain:')+m),...GAIN_MODULES.flatMap(m=>['consume:'+m,'reload:'+m,'rollback:'+m,'after_rollback:'+m])]);
export const SPECIALIST_CHECKS=Object.freeze(['all20_explicit_current_native_baseline_jobs','all20_real_candidate_creation','two_independent_actual_evaluations','only_five_actual_gain_promotions','fifteen_no_gain_promotions_unavailable','bounded_actual_permit_consumption_and_readonly_reload','actual_rollback_then_baseline','no_provider_or_native_action_execution']);
const uuid=v=>typeof v==='string'&&/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(v);
export function validateSpecialistReadback(value,phase){
 assert(value&&typeof value==='object'&&!Array.isArray(value));assert.equal(value.phase,phase);assert.equal(value.providerRuns,0);assert.equal(value.nativeEffectsUnchanged,true);
 if(phase==='baseline'){assert.equal(value.candidates,0);assert.equal(value.promotions,0);assert.equal(value.jobs,0);return value;}
 const [operation,module]=phase.split(':');assert(SPECIALIST_MODULES.includes(module));
 if(['baseline','consume','reload','after_rollback'].includes(operation)){assert(uuid(value.jobId));assert.equal(value.module,module);assert.equal(value.jobKind,'specialist');assert.equal(value.changed,false);assert.equal(value.mode,operation==='consume'||operation==='reload'?'promoted':'baseline');assert.equal(value.used,operation==='baseline'?0:1);}
 else{assert(uuid(value.candidateId));assert.equal(value.module,module);assert.equal(value.playbook,'canonical_followup_v1');if(operation==='evaluate1'||operation==='evaluate2'){assert.equal(value.evaluations,operation==='evaluate1'?1:2);assert.equal(value.passing,GAIN_MODULES.includes(module)?value.evaluations:0);}if(operation==='promote'){assert(uuid(value.promotionId));assert.equal(value.maximum,2);assert.equal(value.used,0);assert.equal(value.retired,false);}if(operation==='no_gain'){assert.equal(value.passing,0);assert.equal(value.promotions,0);}if(operation==='rollback'){assert.equal(value.retired,true);assert.equal(value.used,1);}}
 return value;
}
const card=(page,heading)=>page.locator('[data-ui-card]').filter({has:page.getByRole('heading',{name:heading,exact:true})});
const specialist=page=>page.locator('[data-ui-card]').filter({has:page.locator('summary').filter({hasText:'Module specialists'})});
const form=(section,name)=>section.locator('form').filter({has:section.getByRole('button',{name,exact:true})});
export async function runAssistantSpecialistGovernanceEnglishExperience({page,fixture,verifyCanonical}){
 assert(page&&typeof verifyCanonical==='function'&&fixture?.state==='native_prerequisites_prepared_not_experienced');const base=new URL(page.url()).origin,ids=new Map(),promotions=new Map(),jobs=new Map();
 async function actor(who){assert(uuid(who?.userId));await page.goto(base+'/login');await page.locator(`form[action="/login/as"]:has(input[name="userId"][value="${who.userId}"]) button[type="submit"]`).click();await page.waitForURL(u=>!['/login','/login/as'].includes(u.pathname));await page.goto(base+'/assistant');}
 async function submit(section,name){const [response]=await Promise.all([page.waitForResponse(r=>r.request().method()==='POST'&&new URL(r.url()).origin===base&&new URL(r.url()).pathname==='/assistant'),section.getByRole('button',{name,exact:true}).click()]);assert(response.ok()||response.status()===303);await response.finished();await page.waitForLoadState('networkidle');assert(!new URL(page.url()).searchParams.has('error'));}
 async function read(module,phase){await page.goto(base+'/assistant');const section=card(page,'Module specialist guidance');await section.locator('select[name="module"]').selectOption(module);await submit(section,'Read current module facts');const id=new URL(page.url()).searchParams.get('governed');assert(uuid(id));const native=validateSpecialistReadback(await verifyCanonical({phase,jobId:id}),phase);jobs.set(module,id);assert.equal(native.jobId,id);return native;}
 async function openReview(){await page.goto(base+'/assistant');const section=specialist(page);await section.locator('summary').click();return section;}
 await actor(fixture.actors.operator);validateSpecialistReadback(await verifyCanonical({phase:'baseline'}),'baseline');
 for(const module of SPECIALIST_MODULES)await read(module,'baseline:'+module);
 for(const module of SPECIALIST_MODULES){const section=await openReview(),create=form(section,'Create candidate');await create.locator('select[name="moduleVersion"]').selectOption({value:module+':1'});await create.locator('select[name="playbook"]').selectOption('canonical_followup_v1');await submit(create,'Create candidate');const native=validateSpecialistReadback(await verifyCanonical({phase:'create:'+module}),'create:'+module);ids.set(module,native.candidateId);}
 for(const [index,reviewer]of fixture.actors.reviewers.entries()){
  assert(index<2);await actor(reviewer);
  for(const module of SPECIALIST_MODULES){const section=await openReview(),evaluate=form(section,'Evaluate candidate');await evaluate.locator('select[name="candidateId"]').selectOption(ids.get(module));await evaluate.locator('input[name="consented"]').check();await submit(evaluate,'Evaluate candidate');validateSpecialistReadback(await verifyCanonical({phase:'evaluate'+(index+1)+':'+module}),'evaluate'+(index+1)+':'+module);}
 }
 for(const module of SPECIALIST_MODULES){const section=await openReview(),promote=form(section,'Promote reviewed candidate');if(!GAIN_MODULES.includes(module)){assert.equal(await promote.locator(`select[name="candidateId"] option[value="${ids.get(module)}"]`).count(),0);validateSpecialistReadback(await verifyCanonical({phase:'no_gain:'+module}),'no_gain:'+module);continue;}await promote.locator('select[name="candidateId"]').selectOption(ids.get(module));await promote.locator('input[name="maxJobs"]').fill('2');await promote.locator('input[name="hours"]').fill('1');await submit(promote,'Promote reviewed candidate');const native=validateSpecialistReadback(await verifyCanonical({phase:'promote:'+module}),'promote:'+module);promotions.set(module,native.promotionId);}
 await actor(fixture.actors.operator);
 for(const module of GAIN_MODULES){await read(module,'consume:'+module);await page.reload();validateSpecialistReadback(await verifyCanonical({phase:'reload:'+module,jobId:jobs.get(module)}),'reload:'+module);const section=await openReview(),rollback=form(section,'Roll back promotion');await rollback.locator('select[name="promotionId"]').selectOption(promotions.get(module));await submit(rollback,'Roll back promotion');validateSpecialistReadback(await verifyCanonical({phase:'rollback:'+module}),'rollback:'+module);await read(module,'after_rollback:'+module);}
 return{journey:'english_specialist_governance',checks:SPECIALIST_CHECKS.map(id=>({id,passed:true})),coverage:'all20_actual_baselines_and_independent_evaluations_five_promoted_only_no_live_provider_or_actions'};
}
